diff --git a/core/forks/compare.js b/core/forks/compare.js
index a5e09b3..d8a8fc1 100644
--- a/core/forks/compare.js
+++ b/core/forks/compare.js
@@ -19,7 +19,13 @@ function comparableBranch(branch, fork, verification) {
     if (!['passed', 'failed'].includes(evidence.status)) reasons.push('outcome-inconclusive');
   }
   if (!branch.receipt_digest) reasons.push('receipt-missing');
-  if (fork.schema_version === EXECUTOR_FORK_SCHEMA_VERSION
+  // A fresh verification that actively fails outranks the stored
+  // `receipt_verified` flag on every schema. A resume after an interrupted
+  // receipt write leaves a stale or mismatched receipt on disk that still
+  // satisfies the stored flag. Schema 2 additionally fails closed when no
+  // receipt could be verified at all.
+  if (verification && verification.status === 'invalid') reasons.push('fork-receipt-unverified');
+  else if (fork.schema_version === EXECUTOR_FORK_SCHEMA_VERSION
     && (!verification || verification.status !== 'verified')) {
     reasons.push('fork-receipt-unverified');
   }
