     }
+    // Schema 1 keeps schema 2's taxonomy: an absent signer is `unknown` (there
+    // is nothing to check), a present but unusable one is `invalid`.
+    let pem;
+    try { pem = readPrivate(projectRoot, fork.fork_id, 'signing-key.pem'); } catch (_error) {
+      return { key: null, result: verification('unknown', 'FORK_SIGNER_KEY_MISSING') };
+    }
     return {
-      key: crypto.createPublicKey(readPrivate(projectRoot, fork.fork_id, 'signing-key.pem')),
+      key: crypto.createPublicKey(pem),
       result: verification('verified', 'FORK_LEGACY_SIGNER_LOADED'),
     };
   } catch (_error) {
diff --git a/core/forks/lifecycle.js b/core/forks/lifecycle.js
index cf16965..7465e36 100644
--- a/core/forks/lifecycle.js
+++ b/core/forks/lifecycle.js
@@ -88,9 +88,14 @@ function updateBranch(fork, branchId, changes, now) {
  * Schema 2 decisions are fail-closed: the caller must hand in the result of a
  * fresh cryptographic verification of the stored fork receipt wrapper. Omitting
  * it rejects the decision instead of trusting the record.
+ *
+ * A fresh verification that actively fails is binding on every schema, so a
+ * stale or mismatched receipt left by an interrupted run cannot be decided on.
+ * Schema 1 keeps the legacy path only while nothing contradicts the record.
  */
 function assertVerifiedReceipt(fork, branchId, verification) {
-  if (fork.schema_version !== EXECUTOR_FORK_SCHEMA_VERSION) return;
+  const contradicted = Boolean(verification) && verification.status === 'invalid';
+  if (!contradicted && fork.schema_version !== EXECUTOR_FORK_SCHEMA_VERSION) return;
   if (!verification || verification.status !== 'verified') {
     throw Object.assign(new Error('Branch executor receipt is not cryptographically verified'), {
       code: 'FORK_RECEIPT_UNVERIFIED',
diff --git a/scripts/test-operation-fork.js b/scripts/test-operation-fork.js
index 9c367c7..31b3601 100644
--- a/scripts/test-operation-fork.js
+++ b/scripts/test-operation-fork.js
@@ -119,6 +119,28 @@ assert.equal(resumed.fork.branches.find((branch) => branch.runtime === 'claude')
 assert.equal(resumed.fork.branches.find((branch) => branch.runtime === 'claude').failure_code, 'RUNTIME_EFFECT_AMBIGUOUS');
 assert.deepEqual(calls, ['codex'], 'ambiguous Claude effect must not run again');

+// An interrupted receipt write leaves durable receipt state that no longer
+// matches the branch it claims to prove. Resuming must re-verify from disk and
+// refuse the stale receipt instead of trusting the recorded receipt_verified.
+const raceDirectory = forks.forkDirectory(project, 'fork-auth-race', false);
+fs.copyFileSync(path.join(raceDirectory, 'receipts', 'branch-codex.json'),
+  path.join(raceDirectory, 'receipts', 'branch-claude.json'));
+const stale = forks.loadFork(project, 'fork-auth-race');
+const staleEvidence = forks.forkEvidence(project, stale);
+assert.equal(staleEvidence.get('branch-claude').verification.status, 'invalid');
+assert.equal(staleEvidence.get('branch-codex').verification.status, 'verified');
+const staleComparison = forks.compareFork(stale, { evidence: staleEvidence });
+const staleBranch = staleComparison.branches.find((branch) => branch.branch_id === 'branch-claude');
+assert.equal(staleBranch.comparable, false, 'a mismatched receipt must not stay comparable');
+assert(staleBranch.reasons.includes('fork-receipt-unverified'));
+assert.equal(staleComparison.comparable_count, 1);
+assert.equal(staleComparison.outcome, 'insufficient-evidence',
+  'a fork cannot recommend a winner once one receipt fails fresh verification');
+assert.throws(() => forks.applySelection({ projectRoot: project, forkId: 'fork-auth-race',
+  branchId: 'branch-claude', expectedRevision: stale.revision, actorId: 'actor-operator',
+  idempotencyKey: 'stale-receipt-selection-001', reason: 'stale receipt' }),
+(error) => error.code === 'FORK_RECEIPT_UNVERIFIED', 'a mismatched receipt must not be selectable');
+
 for (const branch of [...result.fork.branches, ...recovery.branches]) {
   const target = provider.resolve(project, worktrees, branch.run_id.includes('recovery') ? 'fork-recovery' : 'fork-auth-race', branch.branch_id);
   if (fs.existsSync(target)) git(project, ['worktree', 'remove', '--force', target]);
